package com.cpf.core.common.tenant;import com.cpf.core.api.tenant.CpfTenant;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class CpfTenantContextTest{@Test void restoresNestedScope(){assertTrue(CpfTenantContext.current().isEmpty());try(var a=CpfTenantContext.open(new CpfTenant("A","A"))){assertEquals("A",CpfTenantContext.current().orElseThrow().tenantId());try(var b=CpfTenantContext.open(new CpfTenant("B","B"))){assertEquals("B",CpfTenantContext.current().orElseThrow().tenantId());}assertEquals("A",CpfTenantContext.current().orElseThrow().tenantId());}assertTrue(CpfTenantContext.current().isEmpty());}}